from pathlib import Path
import json
H=Path(__file__).resolve().parent;R=H.parents[3];C=H.parent/'2026-09-19-review-comparison';prefix=H.relative_to(R).as_posix()+'/'
def text(room,before=False):return ((H/'before' if before else R)/'commons/maps'/room/'final.md').read_text(encoding='utf-8')
def para(t,start):return next(v for v in t.split('\n\n') if v.startswith(start))
A='AdvancedLaboratory_Lab_Equipment_Simulation';Z='PostCrisis_Synthesis'
old,new=text(A,True),text(A);oz,nz=text(Z,True),text(Z)
p=C/'postfoundationscrisis.json';d=json.loads(p.read_text(encoding='utf-8'))
d['items']=[v for v in d['items'] if v['title']!='Next: which body has the catalogue imagined?' and not v.get('report','').startswith(prefix)]
d['status']='All eight halls reviewed in this pass; embodied development continues'
d['summary']='The closing sequence moves from distinctions, participation and disagreement to shared objects, connections and possible bodies. The final assembly follows a reusable instance through changing form; the ledger returns us to the opening clock and to a particular thing we want to make. This closes the review pass, while full-scale inhabitable encounters remain a priority.'
d['items'] += [dict(title='One instance, another body',description='An amber ring follows the same carrier from body joint to chair panel. Unused carriers move visibly to the sides, leaving room to see the assembly. The collection is mutable; its catalogue, target positions and declared bonds shape what it can become.',images=[prefix+'assembly-vrbody.png',prefix+'assembly-chair.png'],captions=['A body assembled from the catalogue. The ring follows its central joint.','The same instance becomes a chair panel; surplus body parts join the surrounding inventory.'],image_note='Current Godot states, same camera and persistent instance. Eighteen simulated seconds of the actual spring calculation settle each form. These are visual parts, not a body you can wear or a chair that supports you.',text_kind='book',before=para(old,'Choose a visible') if 'Choose a visible' in old else old.split('\n\n')[3],after=para(new,'Walk around')+'\n\n'+para(new,'The floating inventory'),report=prefix+A+'/final.diff',report_label='Exact assembly manuscript diff'),
dict(title='The count survives what it forgets',description='The ledger holds six prewritten examples. Its cumulative counter continues as earlier entries leave the display. Slower timing and physical text make that existing operation easier to read.',images=[prefix+'synthesis-ledger.png',prefix+'synthesis-later.png'],captions=['Six visible examples; counter 20.','Six further arrivals; counter 26. Earlier entries have gone.'],image_note='Current Godot captures from the same camera; the probe advances six entries between views. The display does not store visitor decisions or certify a repair. Headset reading remains untested.',text_kind='book',before=para(oz,'The exhibit cycles'),after=para(nz,'The exhibit cycles'),report=prefix+Z+'/final.diff',report_label='Exact synthesis manuscript diff'),
dict(title='The return can begin with desire',description='The final chapter keeps accountability specific and also asks what the visitor wanted to inhabit. The ending returns to the clock from Point One.',text_kind='book',before=para(oz,'Go back'),after=para(nz,'Or remember')+'\n\n'+para(nz,'Go back')+'\n\n'+para(nz,'The clock'),report=prefix+'SUMMARY.md',report_label='Findings, decisions and verification'),
dict(title='Reading the whole book',description='Three parallel close readings cover all 24 sequences, including the code and notes. The assessment distinguishes mature passages from missing encounters and identifies where the investigative voice becomes a repeated review format.',report='doc/book/iterations/2026-09-20-book-reading/index.html',report_label='Whole-book assessment and reading reports')]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Published the closing two halls.')
